def fewestIntervalsCovering(points, intervals):
    pts = sorted(points)
    ivs = sorted(intervals)
    m = len(ivs)
    j = 0
    best = -1
    covered_until = -1
    count = 0
    for x in pts:
        if x <= covered_until:
            continue
        while j < m and ivs[j][0] <= x:
            if ivs[j][1] > best:
                best = ivs[j][1]
            j += 1
        if best < x:
            return -1
        count += 1
        covered_until = best
    return count
